-- Rifts World Book 34: Northern Gun Two, the priced modular hovercycle weapons, housings and radar (printed 158-160)
-- 21 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~316-northern-gun-2-hovercycles-a-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-hm10-light-machine-gun', 'NG-HM10 Light Machine-Gun', 'rifts', 'weapon', NULL, 5000, '5,000 credits for the gun, installed in a fixed forward housing on an E-Clip supply. Ammunition is 2 credits a round (1,200 for 600); silver-coated rounds 100 credits or more each, by the local price of silver. A micro-nuclear battery is 460,000 more.', '1D6x10 S.D.C. per 15-round burst, 2D6x10 S.D.C. per 30-round burst; a 50-round burst does 1D4 M.D. (3D6x10 S.D.C./Hit Points)', 1, '2,000 ft (610 m)', '600 rounds: 12 M.D. bursts, or 40 short S.D.C. bursts', 'Bursts only; each burst, whatever its size, counts as one melee attack', NULL, NULL, NULL, 'A modular nose machine-gun for any hovercycle. Little bought now for its small M.D. payload, its recoil (-10% piloting in the melee round it fires) and the weight of its ammunition, except by riders who want silver rounds against vampires, werebeasts and other creatures harmed by silver.', 'Rifts World Book 34: Northern Gun Two p.158', NULL),
  ('ng-hl12-short-range-ion-blaster', 'NG-HL12 Short-Range Ion Blaster', 'rifts', 'weapon', NULL, 24000, '24,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '3D6 M.D.', 1, '600 ft (183 m)', '12 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular short-range ion blaster for any hovercycle.', 'Rifts World Book 34: Northern Gun Two p.158', NULL),
  ('ng-hi16-medium-range-ion-blaster', 'NG-HI16 Medium-Range Ion Blaster', 'rifts', 'weapon', NULL, 32000, '32,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '3D6 M.D.', 1, '1,200 ft (366 m)', '12 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular medium-range ion blaster for any hovercycle; half of the Hornet''s common nose loadout.', 'Rifts World Book 34: Northern Gun Two p.158-159', NULL),
  ('ng-hi18-heavy-ion-blaster', 'NG-HI18 Heavy Ion Blaster', 'rifts', 'weapon', NULL, 45000, '45,000 credits, installed in a fixed forward housing on a standard E-Clip; the Jouster entry says it normally sells for 60,000 in a ball turret. A micro-nuclear battery is 460,000 more.', '4D6 M.D.', 1, '1,200 ft (366 m)', '6 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular heavy ion blaster for any hovercycle; the Jouster''s standard nose gun.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-hl40-short-range-light-laser', 'NG-HL40 Short-Range Light Laser', 'rifts', 'weapon', NULL, 14000, '14,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '1D6 M.D.', 1, '1,200 ft (366 m)', '40 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular light laser for any hovercycle.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-hl20-long-range-medium-laser', 'NG-HL20 Long-Range Medium Laser', 'rifts', 'weapon', NULL, 25000, '25,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '2D6 M.D.', 1, '2,000 ft (610 m)', '20 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular long-range medium laser for any hovercycle; half of the Hornet''s common nose loadout.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-hl10-long-range-heavy-laser', 'NG-HL10 Long-Range Heavy Laser', 'rifts', 'weapon', NULL, 35000, '35,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '3D6 M.D.', 1, '2,000 ft (610 m)', '10 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular long-range heavy laser for any hovercycle.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-hp6-medium-plasma-ejector', 'NG-HP6 Medium Plasma Ejector', 'rifts', 'weapon', NULL, 80000, '80,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '4D6 M.D.', 1, '1,600 ft (488 m)', '6 shots per E-Clip', 'Single shot only; each counts as one melee attack', NULL, NULL, NULL, 'A modular plasma ejector for any hovercycle. It cannot be combined in the NG-OUE2 over-and-under system.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-hpart-particle-beam', 'NG-HPART Particle Beam', 'rifts', 'weapon', NULL, 150000, '150,000 credits, installed in a fixed forward housing on a standard E-Clip; a micro-nuclear battery is 460,000 more.', '6D6 M.D.', 1, '1,200 ft (366 m)', '4 shots per E-Clip', 'Single shot only', NULL, NULL, NULL, 'The heaviest modular hovercycle gun, a short-ranged particle beam. It cannot be combined in the NG-OUE2 over-and-under system.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-oue2-dual-weapon-system', 'NG-OUE2 Dual Weapon System (Over and Under Combined Energy Weapons)', 'rifts', 'gear', NULL, 15000, '15,000 credits to join two weapons into one mechanism, on top of each weapon''s own price; linked fire is 4,500 more and a turret is extra.', 'As each of the two weapons; one always does more than the other', 1, 'As each of the two weapons', 'As each weapon; usually 10-20 blasts per E-Clip apiece', 'A single blast, or a linked double blast, counts as one melee attack', NULL, NULL, NULL, 'A nose mounting that stacks one heavy and one light energy weapon, never two alike and never plasma or particle beam, each fed by its own one or two E-Clips. Fixed forward or in a simple, basic or ball turret. The rider fires either gun alone or switches between them; linked fire, both at one target at once, is an extra.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-dh2-dual-weapon-system-housing', 'NG-DH2 Dual Weapon System Housing', 'rifts', 'gear', NULL, 15000, '15,000 credits to join two identical weapons into one mechanism, on top of each weapon''s own price; linked fire is 4,500 more and a turret is extra.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The NG-OUE2 arrangement for a pair of identical weapons, fixed forward or in one of the hovercycle turret housings.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-ht01-fixed-forward-weapon-housing', 'HT-01 Fixed Forward Weapon Housing', 'rifts', 'gear', NULL, 2000, '2,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A hovercycle mounting for one or two weapons in the nose, on a side or on a wing, locked to fire straight ahead with no movement at all.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-ht03-forward-facing-arcing-weapon-housing', 'HT-03 Forward Facing Arcing Weapon Housing', 'rifts', 'gear', NULL, 4000, '4,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A hovercycle mounting for one or two forward-firing weapons in the nose, on a side or on a wing, able to tilt 45 degrees up and down.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-ht05-simple-weapon-turret-housing', 'HT-05 Weapon Turret Housing, Simple', 'rifts', 'gear', NULL, 6500, '6,500 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A simple hovercycle turret for one or two weapons, turning 90 degrees left and right with a 20 degree up and down arc; it shoots wherever it points.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-ht07-basic-weapon-turret-housing', 'HT-07 Weapon Turret Housing, Basic', 'rifts', 'gear', NULL, 8500, '8,500 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A basic hovercycle turret for one or two weapons, turning through 180 degrees (never fully rearward) with a 20-45 degree up and down arc.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-ht09-ball-turret-housing', 'HT-09 Ball Turret Housing, Nose Gun', 'rifts', 'gear', NULL, 12500, '12,500 credits small, 20,000 medium, 26,500 large; the lowest is stored.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A ball turret for one or two weapons, swivelling in every direction through 45 to 180 degrees by turret, placement and bike. Medium and large ones usually add 1-3 small spotlights, a nose camera or a targeting laser, or all of these; most look much alike.', 'Rifts World Book 34: Northern Gun Two p.159', NULL),
  ('ng-mm62-dual-mini-missile-tube-launchers', 'NG-MM62 Dual Mini-Missile Tube Launchers', 'rifts', 'weapon', NULL, 20000, '20,000 credits for the launcher; missiles extra.', 'By mini-missile type; usually plasma 1D6x10 M.D., armor piercing 1D4x10 M.D. or fragmentation 5D6 M.D.; smoke and tear gas are sometimes offered', 1, 'One mile (1.6 km)', 'Two, one in each tube', 'One missile at a time, or both', NULL, NULL, NULL, 'A small two-tube launcher, like a pair of fat shotgun barrels, holding one mini-missile per tube. Most hovercycles take one pair on the nose, one underneath, one or two on a side and one at the rear; a winged bike may carry one or two pairs per wing. The entry''s text calls it the M66 Dual Tube Launcher.', 'Rifts World Book 34: Northern Gun Two p.159-160', NULL),
  ('ng-mm64-mini-missile-box-launcher', 'NG-MM64 Mini-Missile Box or Cylinder Launcher (Multi-Shot)', 'rifts', 'weapon', NULL, 50000, '50,000 credits holding four mini-missiles, 70,000 holding six; the lowest is stored. Missiles extra.', 'By mini-missile type', 1, 'One mile (1.6 km)', 'Four or six, stacked', 'One at a time or two together; the next two drop into place once the first pair clears', NULL, NULL, NULL, 'A box launcher, or a cylinder that looks like a thruster jet, mounted fixed forward on the nose, one on each side, or one per wing on a winged bike. Drag: one costs 5% of speed and -2% piloting; one on each side doubles both.', 'Rifts World Book 34: Northern Gun Two p.160', NULL),
  ('ng-mm68-mini-missile-pod-launcher', 'NG-MM68 Mini-Missile Pod Launcher (Multi-Shot)', 'rifts', 'weapon', NULL, 110000, '110,000 credits; missiles extra.', 'By mini-missile type', 1, 'One mile (1.6 km)', 'Eight mini-missiles per pod, 16 for a pod on each side', 'One at a time or volleys of 2, 4 or 6', NULL, NULL, NULL, 'A side-only missile pod, too big for a wing, the nose or the back: a suitcase-like box on a clamp that rotates fully, so it fires forward, up, down or behind. Heavy drag: one pod costs 15% of speed and -10% piloting, a pair doubles both. The Hornet''s usual pods.', 'Rifts World Book 34: Northern Gun Two p.160', NULL),
  ('ng-ws604-wing-sponson-missile-cluster', 'NG-WS604 Wing Sponson Missile Cluster (Multi-Shot)', 'rifts', 'weapon', NULL, 14500, '14,500 credits for the sponson and its launch system; missiles extra.', 'By mini-missile type', 1, 'One mile (1.6 km)', 'Two or four mini-missiles per wing', '1, 2 or 4 mini-missiles', NULL, NULL, NULL, 'A cheap open missile rack, one per wing, for the new winged hovercycles. Drag is slight: 2% of speed, doubled with one on each wing. The missiles sit fully exposed, and a missile or grenade doing more than 15 M.D. to the rack sets them all off, doing full damage to the bike and its rider and probably killing him.', 'Rifts World Book 34: Northern Gun Two p.160', NULL),
  ('ng-hovercycle-radar-comms-unit', 'Radar Comms Unit (hovercycle)', 'rifts', 'gear', NULL, 20000, '20,000 credits.', NULL, 0, 'Radar 40 miles (64 km); radio 5 miles (8 km)', NULL, NULL, NULL, NULL, NULL, 'An add-on radar dish and simple communications array for a hovercycle. The radar follows 48 airborne targets above the treeline, missiles, aircraft, power armor and Xiticix among them; the array picks up commercial and police radio and works as a short-range two-way radio. Both link to helmet radios and HUDs.', 'Rifts World Book 34: Northern Gun Two p.160', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 21 gear rows are in' AS assertion, count(*) AS got, 21 AS want
  FROM gear WHERE slug IN ('ng-hm10-light-machine-gun', 'ng-hl12-short-range-ion-blaster', 'ng-hi16-medium-range-ion-blaster', 'ng-hi18-heavy-ion-blaster', 'ng-hl40-short-range-light-laser', 'ng-hl20-long-range-medium-laser', 'ng-hl10-long-range-heavy-laser', 'ng-hp6-medium-plasma-ejector', 'ng-hpart-particle-beam', 'ng-oue2-dual-weapon-system', 'ng-dh2-dual-weapon-system-housing', 'ng-ht01-fixed-forward-weapon-housing', 'ng-ht03-forward-facing-arcing-weapon-housing', 'ng-ht05-simple-weapon-turret-housing', 'ng-ht07-basic-weapon-turret-housing', 'ng-ht09-ball-turret-housing', 'ng-mm62-dual-mini-missile-tube-launchers', 'ng-mm64-mini-missile-box-launcher', 'ng-mm68-mini-missile-pod-launcher', 'ng-ws604-wing-sponson-missile-cluster', 'ng-hovercycle-radar-comms-unit') AND source_book IS NOT NULL;

